import React from 'react';
import Navigation from '../components/Navigation';
import certification1 from '../media/Azure_Data_Scientist.png';
import certification2 from '../media/Azure_Data_Engineer.png';
import certification3 from '../media/Certificat_HEC_GeorfBAMBA.png'; // Remplacez par le chemin correct
import certification4 from '../media/Berkeley_Georf_MIGUIAMA.PNG'; // Remplacez par le chemin correct

const Certification = () => {
    return (
        <div className="certifications">
            <Navigation />
            <div className="certification-images">
                <img src={certification1} alt="Certification Azure Data Scientist" />
                <img src={certification2} alt="Certification Azure Data Engineer" />
                <img src={certification3} alt="Certification 3" />
                <img src={certification4} alt="Certification 4" />
            </div>
        </div>
    );
};

export default Certification;
